const AWS = require('aws-sdk');

// Lambda handler for user profile lookup service
// Deployed behind API Gateway with Lambda Proxy Integration
exports.handler = async (event) => {
  const queryParams = event.queryStringParameters || {};
  const searchTerm = queryParams.q || '';
  const format = queryParams.format || 'html';
  const callback = queryParams.callback || null;

  // Fetch user data from DynamoDB
  const dynamodb = new AWS.DynamoDB.DocumentClient();
  let results = [];

  try {
    const params = {
      TableName: process.env.USERS_TABLE || 'users',
      FilterExpression: 'contains(displayName, :search)',
      ExpressionAttributeValues: {
        ':search': searchTerm
      }
    };
    const data = await dynamodb.scan(params).promise();
    results = data.Items || [];
  } catch (err) {
    console.error('DynamoDB error:', err);
  }

  // Build response based on format
  if (format === 'json' || callback) {
    const jsonBody = JSON.stringify({ query: searchTerm, results: results });
    // JSONP support for legacy clients
    if (callback) {
      return {
        statusCode: 200,
        headers: {
          'Content-Type': 'application/javascript',
          'X-Request-Id': event.requestContext?.requestId || 'unknown'
        },
        body: `${callback}(${jsonBody});`
      };
    }
    return {
      statusCode: 200,
      headers: { 'Content-Type': 'application/json' },
      body: jsonBody
    };
  }

  // HTML response with search results
  const resultsHtml = results.map(r => 
    `<li class="result-item">${r.displayName} - ${r.email}</li>`
  ).join('');

  const htmlBody = `<!DOCTYPE html>
<html>
<head><title>User Search</title></head>
<body>
  <h1>Search Results</h1>
  <div class="search-info">
    <p>You searched for: <strong>${searchTerm}</strong></p>
    <p>Found ${results.length} result(s)</p>
  </div>
  <ul class="results">${resultsHtml}</ul>
  <form method="GET" action="/search">
    <input type="text" name="q" value="${searchTerm}" />
    <button type="submit">Search</button>
  </form>
</body>
</html>`;

  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'no-store'
    },
    body: htmlBody
  };
};
